package readings
import "errors"
func CheckHumidity(v int) error {
    if v < 0 || v > 100 { return errors.New("HUMIDITY_RANGE") }
    return nil
}
func CheckPressure(v int) error {
    if v < 800 || v > 1200 { return errors.New("PRESSURE_RANGE") }
    return nil
}

