package readings
import "testing"
func TestHumidityBounds(t *testing.T) {
    cases := []struct { name string; value int; rejected bool }{
        {"below_floor", -1, true},
        {"at_ceiling", 100, false},
        {"above_ceiling", 101, true},
    }
    for _, tc := range cases {
        t.Run(tc.name, func(t *testing.T) {
            err := CheckHumidity(tc.value)
            if (err != nil) != tc.rejected { t.Fatalf("value=%d err=%v", tc.value, err) }
        })
    }
}

